function split(bill, tipPercent, people) {
  if ([bill, tipPercent, people].some((x) => String(x).trim() === "")) return null;
  const b = Number(bill), t = Number(tipPercent), p = Number(people);
  if (![b, t, p].every(Number.isFinite) || b < 0 || t < 0 || p < 1) return null;
  return Math.ceil((b * (1 + t / 100)) / p);
}

const ids = ["bill", "tip", "people"];
function update() {
  const [b, t, p] = ids.map((id) => document.getElementById(id).value);
  const each = split(b, t, p);
  document.getElementById("each").textContent = each === null ? "Fill in the bill and people" : `Each pays ${each.toLocaleString()} KSh`;
}
for (const id of ids) {
  document.getElementById(id).addEventListener("input", update);
  document.getElementById(id).addEventListener("change", update);
}
